def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inverse(a, m):
    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        raise ValueError("Modular inverse does not exist")
    else:
        return x % m

def matrix_mod_inv(matrix, mod):
    n = len(matrix)
    adj = [[0 for _ in range(n)] for _ in range(n)]
    det = 0
    for i in range(n):
        for j in range(n):
            minor = [row[:j] + row[j+1:] for row in matrix[1:]]
            if (i+j) % 2 == 0:
                adj[i][j] = determinant(minor)
            else:
                adj[i][j] = -determinant(minor)
        det += matrix[0][i] * adj[0][i]
    det %= mod
    inv_det = mod_inverse(det, mod)
    for i in range(n):
        for j in range(n):
            adj[i][j] = (adj[j][i] * inv_det) % mod

def determinant(matrix):
    if len(matrix) == 1:
        return matrix[0][0]
    det = 0
    sign = 1
    for i in range(len(matrix)):
        submatrix = [row[:i] + row[i+1:] for row in matrix[1:]]
        det += sign * matrix[0][i] * determinant(submatrix)
        sign *= -1
    return det

def gaussian_elimination(matrix, mod):
    n = len(matrix)
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                max_row = j
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]
        for j in range(i+1, n):
            factor = (matrix[j][i] * mod_inverse(matrix[i][i], mod)) % mod
            for k in range(n):
                matrix[j][k] = (matrix[j][k] - factor * matrix[i][k]) % mod
    return matrix

